package com.nulp.mobilepartsshop.core.entity.telemetry;

/**
 * Defines all possible telemetry event types generated by clients or staff.
 * Grouped by their primary domain: General system events, Client shopping behavior, and Staff operations.
 */
public enum EventType {

    // ==========================================
    // GENERAL EVENTS (Applies to all users & apps)
    // ==========================================

    /**
     * Triggered when a new user account is successfully created.
     * Expected Payload: {"role": "CUSTOMER" | "STAFF"}
     */
    USER_REGISTERED,

    /**
     * Triggered when a user successfully authenticates into the system.
     * Expected Payload: {"role": "CUSTOMER" | "STAFF"}
     */
    USER_LOGGED_IN,

    /**
     * Triggered when the application is opened or brought to the foreground.
     * Expected Payload: {"osVersion": "Android 14", "appVersion": "1.0.0", "deviceModel": "Pixel 7"}
     */
    APP_SESSION_STARTED,

    /**
     * Triggered when the application is closed or sent to the background.
     * Expected Payload: {"sessionDurationSeconds": 120}
     */
    APP_SESSION_ENDED,

    /**
     * Triggered when an unhandled exception or critical error occurs in the application.
     * Expected Payload: {"error": "NullPointerException", "screen": "MainActivity", "stackTrace": "..."}
     */
    APP_ERROR,


    // ==========================================
    // CLIENT EVENTS (Customer shopping behavior)
    // ==========================================

    /**
     * Triggered when a customer opens the details screen of a specific part.
     * Expected Payload: {"partId": 123, "partName": "Display"}
     */
    PART_VIEWED,

    /**
     * Triggered when a customer submits a review for a part.
     * Expected Payload: {"partId": 123, "rating": 5}
     */
    PART_REVIEW_ADDED,

    /**
     * Triggered when a customer adds a part to their shopping cart.
     * Expected Payload: {"partId": 123, "price": 1500.00}
     */
    CART_ITEM_ADDED,

    /**
     * Triggered when a customer changes the quantity of a specific part already in their shopping cart.
     * Expected Payload: {"partId": 123, "oldQuantity": 1, "newQuantity": 2}
     */
    CART_ITEM_COUNT_CHANGED,

    /**
     * Triggered when a customer removes a part from their shopping cart.
     * Highly valuable for analyzing price rejection or cart abandonment.
     * Expected Payload: {"partId": 123, "price": 1500.00}
     */
    CART_ITEM_REMOVED,

    /**
     * Triggered when a customer successfully completes checkout and creates an order.
     * Expected Payload: {"orderId": 456, "totalAmount": 3000.00, "itemsCount": 2}
     */
    ORDER_CREATED,

    /**
     * Triggered when a customer submits a search query.
     * Expected Payload: {"searchQuery": "s23 ultra battery"}
     */
    SEARCH_PERFORMED,

    /**
     * Triggered when a customer applies filters to a product list or search results.
     * Expected Payload: {"filters": ["Samsung", "Motherboards"]}
     */
    SEARCH_FILTER_APPLIED,

    /**
     * Triggered when a search query returns zero results.
     * Crucial for inventory planning (understanding what users want but cannot find).
     * Expected Payload: {"searchQuery": "iPhone 16 logic board"}
     */
    SEARCH_EMPTY_RESULT,


    // ==========================================
    // STAFF EVENTS (Order processing & management)
    // ==========================================

    /**
     * Triggered when a staff member starts processing a new order.
     * Marks the beginning of the SLA (Service Level Agreement) timer.
     * Expected Payload: {"orderId": 456}
     */
    ORDER_PROCESSING_STARTED,

    /**
     * Triggered when a staff member completes the processing of an order.
     * Used to calculate the total processing time and staff efficiency.
     * Expected Payload: {"orderId": 456, "processingTimeSeconds": 300, "status": "SHIPPED"}
     */
    ORDER_PROCESSING_FINISHED,
}
